package installation

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"slices"

	"github.com/holon-sh/cli/pkg/mcpcontract"
	"github.com/holon-sh/cli/pkg/typegen"
	"github.com/tailscale/hujson"
)

// stageRuntimeSlots fills the installed SDKs' generated/ slots from the build snapshot.
// It runs after package installation, before the build or a type check.
const stageRuntimeSlots = `#!/bin/sh
# Generated by Holon: replace the installed SDKs' generated/ slots with this build's clients.
set -e
for package in holon-sh holon-ui; do
  if [ -d ".holon-types/$package" ] && [ -d "node_modules/$package" ]; then
    rm -rf "node_modules/$package/generated"
    cp -R ".holon-types/$package/generated" "node_modules/$package/generated"
  fi
done
`

// stageTypes writes app's generated clients into its build snapshot and returns the railpack
// configuration that stages them, or "" when it needs none. Python and Go clients are source files;
// the TypeScript clients fill the generated/ slots of the holon-sh and holon-ui packages that the
// app's own install fetches.
func stageTypes(p *preparedTypes) (string, error) {
	targets := p.prepared.Targets(p.name)
	if len(targets) == 0 {
		return "", nil
	}
	directory := filepath.Join(p.root, ".holon-types")
	if err := os.Mkdir(directory, 0o755); err != nil {
		return "", fmt.Errorf("prepare MCP types (.holon-types is reserved): %w", err)
	}
	if err := writeClients(p, p.root); err != nil {
		return "", err
	}
	if !slices.Contains(targets, typegen.TargetTS) && !slices.Contains(targets, typegen.TargetUI) {
		return "", stabilizeTimes(p.root)
	}
	if err := os.WriteFile(filepath.Join(directory, "stage.sh"), []byte(stageRuntimeSlots), 0o755); err != nil {
		return "", err
	}
	if err := stageNodePackage(p.root); err != nil {
		return "", fmt.Errorf("%s: %w", p.name, err)
	}
	config, err := railpackConfig(filepath.Join(p.root, "railpack.json"))
	if err != nil {
		return "", err
	}
	build := objectField(objectField(config, "steps"), "build")
	commands, ok := build["commands"].([]any)
	if !ok {
		commands = []any{"..."}
	}
	build["commands"] = append([]any{"sh .holon-types/stage.sh"}, commands...)
	if err := writeTypeJSON(filepath.Join(directory, "railpack.json"), config); err != nil {
		return "", err
	}
	return ".holon-types/railpack.json", stabilizeTimes(p.root)
}

// writeClients writes p's generated clients into root, laid out as the app's directory: Python and Go
// clients in place, and each TypeScript package's under .holon-types for stage.sh.
func writeClients(p *preparedTypes, root string) error {
	for _, target := range p.prepared.Targets(p.name) {
		path := root
		switch target {
		case typegen.TargetTS:
			path = filepath.Join(root, ".holon-types", nodeRuntime)
		case typegen.TargetUI:
			path = filepath.Join(root, ".holon-types", uiRuntime)
		}
		if err := os.MkdirAll(path, 0o755); err != nil {
			return err
		}
		if err := p.prepared.WriteSlot(p.name, target, path); err != nil {
			return fmt.Errorf("%s: %w", p.name, err)
		}
	}
	return nil
}

func railpackConfig(path string) (map[string]any, error) {
	data, err := os.ReadFile(path)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	config := map[string]any{}
	if len(bytes.TrimSpace(data)) > 0 {
		if data, err = hujson.Standardize(data); err != nil {
			return nil, fmt.Errorf("railpack.json: %w", err)
		}
		if err := json.Unmarshal(data, &config); err != nil {
			return nil, fmt.Errorf("railpack.json: %w", err)
		}
	}
	return config, nil
}

// stageNodePackage stages the generated clients before the build copy's own postinstall.
func stageNodePackage(root string) error {
	path := filepath.Join(root, "package.json")
	var pkg map[string]any
	if err := readTypeJSON(path, &pkg); err != nil {
		return err
	}
	scripts := objectField(pkg, "scripts")
	stage := "[ ! -f .holon-types/stage.sh ] || sh .holon-types/stage.sh"
	if existing, _ := scripts["postinstall"].(string); existing != "" {
		stage += " && " + existing
	}
	scripts["postinstall"] = stage
	return writeTypeJSON(path, pkg)
}

// stabilizeTimes gives the files Holon wrote into the snapshot content-derived mtimes, so BuildKit's
// incremental context sync resends only those that changed.
func stabilizeTimes(root string) error {
	for _, directory := range []string{".holon-types", "holon", "package.json"} {
		err := filepath.WalkDir(filepath.Join(root, directory), func(path string, entry fs.DirEntry, err error) error {
			if err != nil || entry.IsDir() {
				return err
			}
			data, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			return os.Chtimes(path, mcpcontract.StableTime(data), mcpcontract.StableTime(data))
		})
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return err
		}
	}
	return nil
}

func objectField(parent map[string]any, name string) map[string]any {
	value, ok := parent[name].(map[string]any)
	if !ok {
		value = map[string]any{}
		parent[name] = value
	}
	return value
}

func readTypeJSON(path string, value any) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return json.Unmarshal(data, value)
}

func writeTypeJSON(path string, value any) error {
	data, _ := json.MarshalIndent(value, "", "  ")
	return mcpcontract.WriteStable(path, append(data, '\n'), 0o644)
}
